"""Intent tests for risk.log_returns (RISK-01, TC-04)."""

from __future__ import annotations

import pytest

from mdata import Prices
from risk import Returns, log_returns


def _prices(data: dict) -> Prices:
    return Prices(
        dates=tuple(data["dates"]),
        tickers=tuple(data["tickers"]),
        closes={ticker: tuple(values) for ticker, values in data["closes"].items()},
    )


@pytest.mark.intent
def test_tc04_geometric_closes_give_closed_form_log_returns(golden):
    inp, expected = golden("risk", "TC-04")
    tol = expected["tol"]

    returns = log_returns(_prices(inp["prices"]))

    assert isinstance(returns, Returns)
    assert returns.base_date == expected["base_date"]
    assert returns.dates == tuple(expected["dates"])
    assert returns.tickers == tuple(expected["tickers"])
    for ticker in expected["tickers"]:
        assert len(returns.values[ticker]) == len(expected["values"][ticker])
        assert list(returns.values[ticker]) == pytest.approx(
            expected["values"][ticker], rel=0, abs=tol
        )


@pytest.mark.intent
def test_returns_are_dated_after_the_base_date(contract_sample):
    data = contract_sample("mdata.Prices")
    prices = _prices(data)

    returns = log_returns(prices)

    assert returns.base_date == data["dates"][0]
    assert returns.dates == tuple(data["dates"][1:])
    assert returns.tickers == tuple(data["tickers"])
    for ticker in data["tickers"]:
        assert len(returns.values[ticker]) == len(data["dates"]) - 1


@pytest.mark.intent
@pytest.mark.parametrize("n_dates", [0, 1])
def test_fewer_than_two_dates_raises_value_error(contract_sample, n_dates):
    data = contract_sample("mdata.Prices")
    prices = Prices(
        dates=tuple(data["dates"][:n_dates]),
        tickers=tuple(data["tickers"]),
        closes={
            ticker: tuple(values[:n_dates]) for ticker, values in data["closes"].items()
        },
    )

    with pytest.raises(ValueError, match=r".+"):
        log_returns(prices)

